<script setup>
import{computed,onMounted,onBeforeUnmount,ref}from'vue';import{shift,view}from'./labor-model.js';
import{verifyLabor}from'./verify.js';
const props=defineProps({host:Object,initialSettings:Object});const settings=ref({...props.initialSettings}),snapshot=ref(null),now=ref(Date.now()),error=ref(''),saveError=ref(''),loading=ref(false),saving=ref(false),dialog=ref(),start=ref('09:00'),end=ref('18:00'),background=ref('#ffffff'),radius=ref(24);let alive=true,timer,generation=0;
const images=import.meta.glob('./original/images/*.png',{eager:true,query:'?url',import:'default'});
const current=computed(()=>{const result=view(snapshot.value,now.value);return {...result,image:images['./original/images/'+result.emoji.image]};});
const label=computed(()=>{const value=new Date(now.value);return String(value.getHours()).padStart(2,'0')+':'+String(value.getMinutes()).padStart(2,'0');});
const status=computed(()=>props.host.preview?'预览 · 不启动提醒':error.value||current.value.status||snapshot.value?.delivery==='failed'?'提醒或时间读取失败：'+(error.value||current.value.status||snapshot.value?.lastError||'系统未接受通知'):snapshot.value?.delivery==='accepted'?'倒计时已交给系统':snapshot.value?.delivery==='unknown'?'上次提醒递送未确定':'');
function theme(){document.documentElement.style.setProperty('--background',CSS.supports('color',settings.value.background)?settings.value.background:'#ffffff');document.documentElement.style.setProperty('--radius',settings.value.radius+'px');}theme();
async function refresh(){if(!alive||loading.value||saving.value)return;loading.value=true;const stamp=generation;try{const result=props.host.preview?{...shift(settings.value,Date.now()),sampledAt:Date.now(),delivery:'',lastError:null}:await props.host.request('labor.get');if(!alive||stamp!==generation)return;snapshot.value=result;error.value='';}catch(reason){if(alive&&stamp===generation)error.value=String(reason?.message||reason);}finally{loading.value=false;}}
onMounted(async()=>{await props.host.ready();if(!alive)return;await refresh();timer=setInterval(()=>{now.value=Date.now();void refresh();},1000);void verifyLabor({host:props.host,images,getState:()=>({settings:settings.value,snapshot:snapshot.value,current:current.value,loading:loading.value,saving:saving.value})});});onBeforeUnmount(()=>{alive=false;clearInterval(timer);});
function open(){const value=settings.value;start.value=String(value.startHour).padStart(2,'0')+':'+String(value.startMinute).padStart(2,'0');end.value=String(value.endHour).padStart(2,'0')+':'+String(value.endMinute).padStart(2,'0');background.value=value.background;radius.value=value.radius;saveError.value='';dialog.value.showModal();}
async function save(){if(props.host.preview||saving.value)return;saving.value=true;try{const a=start.value.split(':').map(Number),b=end.value.split(':').map(Number),next={...settings.value,startHour:a[0],startMinute:a[1],endHour:b[0],endMinute:b[1],background:background.value,radius:Number(radius.value)};shift(next,Date.now());const result=await props.host.request('settings.update',next);if(!alive)return;generation++;settings.value=result;snapshot.value=null;theme();dialog.value.close();}catch(reason){if(alive)saveError.value='设置未保存：'+String(reason?.message||reason);}finally{saving.value=false;if(alive)void refresh();}}
</script>
<template><main class="widget"><div class="container"><div class="progress-bar"><div class="progress-outline"><div class="progress" :style="{width:(current.percent??0)+'%'}"/><div class="percent" :style="current.percent>70?{left:'4px'}:{right:'4px'}">{{current.percent===null?'—':current.percent+'%'}}</div></div><div class="thumb" :style="{left:(current.percent??0)+'%',opacity:current.percent===null?.5:1}"><img :src="current.image" class="emoji" alt=""><div class="time">{{label}}</div><div v-if="current.percent!==null" class="second" :style="{left:current.percent>95?'-15px':'50px',animationDuration:current.emoji.duration+'s'}">{{current.emoji.title}}</div></div></div></div><button class="settings" title="打工进度设置" aria-label="打工进度设置" @click="open">⚙</button><output class="status" role="status">{{status}}</output><dialog ref="dialog" @cancel="saving&&$event.preventDefault()"><form @submit.prevent="save"><h2>打工进度设置</h2><label>上班时间<input v-model="start" type="time" required></label><label>下班时间<input v-model="end" type="time" required></label><label>背景颜色<input v-model="background" type="color"></label><label>圆角<input v-model="radius" type="number" min="0" max="60" required></label><div class="actions"><button type="submit" :disabled="host.preview||saving">保存</button><button type="button" :disabled="saving" @click="dialog.close()">关闭</button></div><p class="error">{{saveError}}</p></form></dialog></main></template>
